#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# W010 chain: idle check, governor performance, run_w010.py on CPU 2 (all arms, all cases), governor restored.
set -u
W=$(cd "$1" && pwd); L=$W/run.log
echo "start $(date -u +%FT%TZ); load $(cut -d' ' -f1-3 /proc/loadavg); other monerod/shadow: $(pgrep -x monerod -c)/$(pgrep -x shadow -c)" | tee -a "$L"
if [ "$(pgrep -x monerod -c)" != 0 ] || [ "$(pgrep -x shadow -c)" != 0 ]; then echo "NOT_IDLE" | tee -a "$L"; exit 1; fi
g0=$(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)
sudo cpupower frequency-set -g performance > /dev/null; echo "governor $g0 -> $(cat /sys/devices/system/cpu/cpu2/cpufreq/scaling_governor)" | tee -a "$L"
python3 -I "$W/run_w010.py" "$W" 2 >> "$L" 2>&1; echo "runner rc=$?" | tee -a "$L"
sudo cpupower frequency-set -g "$g0" > /dev/null; echo "governor restored: $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor)" | tee -a "$L"
echo "W010_DONE $(date -u +%FT%TZ)" | tee -a "$L"
